func (this *BaseExchange) CheckConflictingProxies(proxyAgentSet any, proxyUrlSet any) {
	var proxyAgentIsSet bool = (!IsEqual(proxyAgentSet, nil)) && (proxyAgentSet != "")
	var proxyUrlIsSet bool = (!IsEqual(proxyUrlSet, nil)) && (proxyUrlSet != "")
	if proxyAgentIsSet && proxyUrlIsSet {
		panic(InvalidProxySettings(this.Id + " you have multiple conflicting proxy settings, please use only one from : proxyUrl, httpProxy, httpsProxy, socksProxy"))
	}
}
func (this *BaseExchange) CheckAddress(optionalArgs ...any) any {
	address := GetArg(optionalArgs, 0, nil)
	_ = address
	code := GetArg(optionalArgs, 1, nil)
	_ = code
	var tag *string = GetArgStringPtr(optionalArgs, 2, nil)
	_ = tag
	if address == nil {
		panic(InvalidAddress(this.Id + " address is undefined"))
	}
	// check the address is not the same letter like 'aaaaa' nor too short nor has a space
	var uniqChars any = (this.Unique(this.StringToCharsArray(address)))
	var length int = GetArrayLength(uniqChars) // py transpiler trick
	if (length == 1) || (GetLength(address) < this.MinFundingAddressLength) || (GetIndexOf(address, " ") > -1) {
		panic(InvalidAddress(this.Id + " address is invalid or has less than " + ToString(this.MinFundingAddressLength) + " characters: \"" + ToString(address) + "\""))
	}
	if code != nil {
		var tagRequiredCurrencies any = this.SafeList(this.Options, "withdrawTagRequiredCurrencies", []any{})
		if this.InArray(code, tagRequiredCurrencies) {
			if tag == nil {
				panic(ArgumentsRequired(Add(this.Id+" withdraw() requires params[\"tag\"] for ", code)))
			}
		}
	}
	return address
}
func (this *BaseExchange) FindMessageHashes(client *Client, element any) any {
	var result []any = []any{}
	var messageHashes []string = ObjectKeys(client.Futures)
	for i := 0; i < len(messageHashes); i++ {
		var messageHash string = messageHashes[i]
		if GetIndexOf(messageHash, element) >= 0 {
			result = append(result, messageHash)
		}
	}
	return result
}
func (this *BaseExchange) FilterByLimit(array any, optionalArgs ...any) []any {
	limit := GetArg(optionalArgs, 0, nil)
	_ = limit
	key := GetArg(optionalArgs, 1, "timestamp")
	_ = key
	var fromStart bool = GetArgBool(optionalArgs, 2, false)
	_ = fromStart
	if limit != nil {
		var arrayLength int = GetArrayLength(array)
		if arrayLength > 0 {
			var ascending bool = true
			if InOp(GetValue(array, 0), key) {
				var first *float64 = this.SafeFloat(GetValue(array, 0), key)
				var last *float64 = this.SafeFloat(GetValue(array, arrayLength-1), key)
				if (first != nil) && (last != nil) {
					ascending = (*last >= *first) // true if array is sorted in ascending order based on 'timestamp'
				}
			}
			if fromStart == true {
				var limitResolved any = func() any {
					if IsGreaterThan(limit, arrayLength) {
						return arrayLength
					}
					return limit
				}()
				if ascending {
					return this.ArraySlice(array, 0, limitResolved)
				}
				return this.ArraySlice(array, OpNeg(limitResolved))
			}
			if ascending {
				return this.ArraySlice(array, OpNeg(limit))
			}
			return this.ArraySlice(array, 0, limit)
		}
	}
	return this.ToArray(array)
}
func (this *BaseExchange) FilterBySinceLimit(array any, optionalArgs ...any) []any {
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	limit := GetArg(optionalArgs, 1, nil)
	_ = limit
	key := GetArg(optionalArgs, 2, "timestamp")
	_ = key
	var tail bool = GetArgBool(optionalArgs, 3, false)
	_ = tail
	if IsEqual(array, nil) {
		return []any{}
	}
	var sinceIsDefined bool = (since != nil)
	var parsedArray []any = this.ToArray(array)
	var result []any = parsedArray
	if sinceIsDefined {
		result = []any{}
		for i := 0; i < len(parsedArray); i++ {
			var entry any = DerefScalar(parsedArray[i])
			var value *int64 = this.SafeInteger(entry, key)
			if (value != nil) && (value == nil || *value != 0) && (since == nil || *value >= *since) {
				result = append(result, entry)
			}
		}
	}
	if (tail == true) && (limit != nil) {
		return this.ArraySlice(result, OpNeg(limit))
	}
	// if the user provided a 'since' argument
	// we want to limit the result starting from the 'since'
	var shouldFilterFromStart bool = !(tail == true) && sinceIsDefined
	return this.FilterByLimit(result, limit, key, shouldFilterFromStart)
}
func (this *BaseExchange) FilterByValueSinceLimit(array any, field any, optionalArgs ...any) []any {
	value := GetArg(optionalArgs, 0, nil)
	_ = value
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	limit := GetArg(optionalArgs, 2, nil)
	_ = limit
	var key string = GetArgString(optionalArgs, 3, "timestamp")
	_ = key
	var tail bool = GetArgBool(optionalArgs, 4, false)
	_ = tail
	var valueIsDefined bool = this.ValueIsDefined(value)
	var sinceIsDefined bool = (since != nil)
	var parsedArray []any = this.ToArray(array)
	var result []any = parsedArray
	// single-pass filter for both symbol and since
	if valueIsDefined || sinceIsDefined {
		result = []any{}
		for i := 0; i < len(parsedArray); i++ {
			var entry any = DerefScalar(parsedArray[i])
			// safeValue (not entry[field]) so a missing field is a non-match, not a
			// KeyError in python/php — prediction structures key on outcome, not symbol
			var entryFiledEqualValue bool = IsEqual(this.SafeValue(entry, field), value)
			var firstCondition bool = !valueIsDefined || entryFiledEqualValue
			var entryKeyValue *int64 = this.SafeInteger(entry, key)
			var entryKeyGESince bool = (entryKeyValue != nil) && (entryKeyValue == nil || *entryKeyValue != 0) && (since != nil) && (*entryKeyValue >= *since)
			var secondCondition bool = !sinceIsDefined || entryKeyGESince
			if firstCondition && secondCondition {
				result = append(result, entry)
			}
		}
	}
	if (tail == true) && (limit != nil) {
		return this.ArraySlice(result, OpNeg(limit))
	}
	return this.FilterByLimit(result, limit, key, sinceIsDefined)
}

/**
 * @method
 * @name Exchange#setSandboxMode
 * @description set the sandbox mode for the exchange
 * @param {boolean} enabled true to enable sandbox mode, false to disable it
 */
func (this *BaseExchange) SetSandboxMode(enabled bool) {
	if enabled {
		if _, ok := this.Urls["test"]; ok {
			if IsString(this.Urls["api"]) {
				this.Urls["apiBackup"] = this.Urls["api"]
				this.RefreshUrlsViews()
				this.Urls["api"] = this.Urls["test"]
				this.RefreshUrlsViews()
			} else {
				this.Urls["apiBackup"] = this.Clone(this.Urls["api"])
				this.RefreshUrlsViews()
				this.Urls["api"] = this.Clone(this.Urls["test"])
				this.RefreshUrlsViews()
			}
		} else {
			panic(NotSupported(this.Id + " does not have a sandbox URL"))
		}
		// set flag
		this.IsSandboxModeEnabled = true
	} else if _, ok := this.Urls["apiBackup"]; ok {
		if IsString(this.Urls["api"]) {
			this.Urls["api"] = this.Urls["apiBackup"]
			this.RefreshUrlsViews()
		} else {
			this.Urls["api"] = this.Clone(this.Urls["apiBackup"])
			this.RefreshUrlsViews()
		}
		var newUrls map[string]any = MapTyped(this.Omit(this.Urls, "apiBackup"))
		this.Urls = newUrls
		this.RefreshUrlsViews()
		// set flag
		this.IsSandboxModeEnabled = false
	}
}

/**
 * @method
 * @name Exchange#enableDemoTrading
 * @description enables or disables demo trading mode
 * @param {boolean} [enable] true if demo trading should be enabled, false otherwise
 */
func (this *BaseExchange) EnableDemoTrading(enable bool) {
	if this.IsSandboxModeEnabled {
		panic(NotSupported(this.Id + " demo trading does not support in sandbox environment. Please check https://www.binance.com/en/support/faq/detail/9be58f73e5e14338809e3b705b9687dd to see the differences"))
	}
	if enable {
		this.Urls["apiBackupDemoTrading"] = this.Urls["api"]
		this.RefreshUrlsViews()
		this.Urls["api"] = this.Urls["demo"]
		this.RefreshUrlsViews()
	} else if _, ok := this.Urls["apiBackupDemoTrading"]; ok {
		this.Urls["api"] = this.Urls["apiBackupDemoTrading"]
		this.RefreshUrlsViews()
		var newUrls map[string]any = MapTyped(this.Omit(this.Urls, "apiBackupDemoTrading"))
		this.Urls = newUrls
		this.RefreshUrlsViews()
	}
	this.Options["enableDemoTrading"] = enable
}
