func (this *BaseExchange) ParseToInt(number any) int64 {
	// Solve Common parseInt misuse ex: parseInt ((since / 1000).toString ())
	// using a number as parameter which is not valid in ts
	// numberToString is typed as nullable under strictNullChecks; cast to string
	// the cast is erased at transpile-time, so output matches every target language, rather than
	// branching to a bare `NaN` literal, which has no symbol in Go/Java/C#
	var stringifiedNumber *string = this.NumberToString(number)
	var convertedNumber any = ParseFloat(stringifiedNumber)
	return ParseInt(convertedNumber)
}
func (this *BaseExchange) ParseToNumeric(number any) any {
	var stringVersion *string = this.NumberToString(number) // this will convert 1.0 and 1 to "1" and 1.1 to "1.1"
	// keep this in mind:
	// in JS:     1 === 1.0 is true
	// in Python: 1 == 1.0 is true
	// in PHP:    1 == 1.0 is true, but 1 === 1.0 is false.
	if GetIndexOf(stringVersion, ".") >= 0 {
		return ParseFloat(stringVersion)
	}
	return ParseInt(stringVersion)
}
func (this *BaseExchange) IsRoundNumber(value any) bool {
	// this method is similar to isInteger, but this is more loyal and does not check for types.
	// i.e. isRoundNumber(1.000) returns true, while isInteger(1.000) returns false
	var res any = this.ParseToNumeric((Mod(value, 1)))
	return (res == 0)
}
func (this *BaseExchange) IsEmptyString(value any) bool {
	return !this.ValueIsDefined(value) || (value == "")
}
func (this *BaseExchange) SafeIntegerOmitZero(obj any, key any, optionalArgs ...any) any {
	var defaultValue *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = defaultValue
	var timestamp *int64 = this.SafeInteger(obj, key, defaultValue)
	if (timestamp == nil) || (timestamp != nil && *timestamp == 0) {
		return nil
	}
	return timestamp
}
func (this *BaseExchange) AfterConstruct(optionalArgs ...any) {
	// networksById: inverse of options.networks, explicit options.networksById entries win
	var userConfig map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = userConfig
	var networkIdsToCodesGenerated any = this.InvertFlatStringDictionary(this.SafeValue(this.Options, "networks", map[string]any{}))
	this.Options["networksById"] = this.Extend(networkIdsToCodesGenerated, this.SafeValue(this.Options, "networksById", map[string]any{}))
	this.FeaturesGenerator()
	this.HasAutocorrect()
	// init predefined markets if any
	if this.Markets() != nil {
		this.SetMarkets(this.Markets())
	}
	// init the request rate limiter
	this.InitRestRateLimiter()
	// sanbox mode
	var isSandbox *bool = this.SafeBool2(this.Options, "sandbox", "testnet", false)
	if isSandbox != nil && *isSandbox {
		this.DerivedExchange.SetSandboxMode(true)
	}
	// compatibility for sandbox/testnet options in userConfig
	if (this.SafeBool(userConfig, "sandbox", false) != nil && *this.SafeBool(userConfig, "sandbox", false)) || (this.SafeBool(userConfig, "testnet", false) != nil && *this.SafeBool(userConfig, "testnet", false)) {
		this.DerivedExchange.SetSandboxMode(true)
	}
}
func (this *BaseExchange) HasAutocorrect() {
	var fallbacks map[string]any = map[string]any{
		"fetchL2OrderBook":    "fetchOrderBook",
		"createLimitOrder":    "createOrder",
		"createMarketOrder":   "createOrder",
		"createLimitOrderWs":  "createOrderWs",
		"createMarketOrderWs": "createOrderWs",
	}
	var targets []string = nil
	if fallbacks != nil {
		targets = make([]string, 0, len(fallbacks))
		for objectKey := range fallbacks {
			targets = append(targets, objectKey)
		}
	}
	for i := 0; i < len(targets); i++ {
		var target string = targets[i]
		var source any = fallbacks[target]
		var sourceDefined bool = (InOp(this.Has, source)) && (!IsEqual(GetValue(this.Has, source), nil))
		var targetDefined bool = (InOp(this.Has, target)) && (!IsEqual(this.Has[target], nil))
		if sourceDefined && !targetDefined {
			this.Has[target] = GetValue(this.Has, source)
		}
	}
}
func (this *BaseExchange) InitRestRateLimiter() {
	if this.RateLimit == -1 {
		panic(ExchangeError(this.Id + ".rateLimit property is not configured"))
	}
	var refillRate any = this.MAX_VALUE
	if this.RateLimit > 0 {
		refillRate = (1 / this.RateLimit)
	}
	var useLeaky bool = (this.RollingWindowSize == 0) || (this.RateLimiterAlgorithm == "leakyBucket")
	var algorithm string = func() string {
		if useLeaky {
			return "leakyBucket"
		}
		return "rollingWindow"
	}()
	var defaultBucket map[string]any = map[string]any{
		"delay":      0.001,
		"capacity":   1,
		"cost":       1,
		"refillRate": refillRate,
		"algorithm":  algorithm,
		"windowSize": this.RollingWindowSize,
		"rateLimit":  this.RateLimit,
	}
	var existingBucket any = func() any {
		if IsEqual(this.TokenBucket, nil) {
			return map[string]any{}
		}
		return this.TokenBucket
	}()
	this.TokenBucket = this.Extend(defaultBucket, existingBucket)
	this.InitThrottler()
}
func (this *BaseExchange) FeaturesGenerator() {
	//
	// in the exchange-specific features can be something like this, where we support 'string' aliases too:
	//
	//     {
	//         'my' : {
	//             'createOrder' : {...},
	//         },
	//         'swap': {
	//             'linear': {
	//                 'extends': my',
	//             },
	//         },
	//     }
	//
	if this.Features == nil {
		return
	}
	// reconstruct
	var initialFeatures any = this.Features
	this.Features = map[string]any{}
	var unifiedMarketTypes []string = []string{"spot", "swap", "future", "option"}
	var subTypes []string = []string{"linear", "inverse"}
	// atm only support basic methods, eg: 'createOrder', 'fetchOrder', 'fetchOrders', 'fetchMyTrades'
	for i := 0; i < len(unifiedMarketTypes); i++ {
		var marketType string = unifiedMarketTypes[i]
		// if marketType is not filled for this exchange, don't add that in `features`
		if !(InOp(initialFeatures, marketType)) {
			this.Features[marketType] = nil
		} else {
			if marketType == "spot" {
				this.Features[marketType] = this.FeaturesMapper(initialFeatures, marketType)
			} else {
				this.Features[marketType] = map[string]any{}
				for j := 0; j < len(subTypes); j++ {
					var subType string = subTypes[j]
					AddElementToObject(this.Features[marketType], subType, this.FeaturesMapper(initialFeatures, marketType, subType))
				}
			}
		}
	}
}
func (this *BaseExchange) FeaturesMapper(initialFeatures any, marketType any, optionalArgs ...any) any {
	subType := GetArg(optionalArgs, 0, nil)
	_ = subType
	var featuresObj any = func() any {
		if subType != nil {
			return GetValue(GetValue(initialFeatures, marketType), subType)
		}
		return GetValue(initialFeatures, marketType)
	}()
	// if exchange does not have that market-type (eg. future>inverse)
	if IsEqual(featuresObj, nil) {
		return nil
	}
	var extendsStr *string = this.SafeString(featuresObj, "extends")
	if extendsStr != nil {
		featuresObj = this.Omit(featuresObj, "extends")
		var extendObj any = this.FeaturesMapper(initialFeatures, extendsStr)
		featuresObj = this.DeepExtend(extendObj, featuresObj)
	}
	//
	// ### corrections ###
	//
	// createOrder
	if InOp(featuresObj, "createOrder") {
		var value any = this.SafeDict(GetValue(featuresObj, "createOrder"), "attachedStopLossTakeProfit")
		AddElementToObject(GetValue(featuresObj, "createOrder"), "stopLoss", value)
		AddElementToObject(GetValue(featuresObj, "createOrder"), "takeProfit", value)
		if marketType == "spot" {
			// default 'hedged': false
			AddElementToObject(GetValue(featuresObj, "createOrder"), "hedged", false)
			// default 'leverage': false
			if !(InOp(GetValue(featuresObj, "createOrder"), "leverage")) {
				AddElementToObject(GetValue(featuresObj, "createOrder"), "leverage", false)
			}
		}
		// default 'GTC' to true
		if this.SafeBool(GetValue(GetValue(featuresObj, "createOrder"), "timeInForce"), "GTC") == nil {
			AddElementToObject(GetValue(GetValue(featuresObj, "createOrder"), "timeInForce"), "GTC", true)
		}
	}
	// other methods
	var keys []string = ObjectKeys(featuresObj)
	for i := 0; i < len(keys); i++ {
		var key string = keys[i]
		var featureBlock any = GetValue(featuresObj, key)
		if !this.InArray(key, []any{"sandbox"}) && (featureBlock != nil) {
			// default "symbolRequired" to false to all methods (except `createOrder`)
			if !(InOp(featureBlock, "symbolRequired")) {
				AddElementToObject(featureBlock, "symbolRequired", this.InArray(key, []any{"createOrder", "createOrders", "fetchOHLCV"}))
			}
		}
	}
	return featuresObj
}
func (this *BaseExchange) FeatureValue(symbol any, optionalArgs ...any) any {
	/**
	 * @method
	 * @name exchange#featureValue
	 * @description this method is a very deterministic to help users to know what feature is supported by the exchange
	 * @param {string} [symbol] unified symbol
	 * @param {string} [methodName] view currently supported methods: https://docs.ccxt.com/README?id=features
	 * @param {string} [paramName] unified param value, like: `triggerPrice`, `stopLoss.triggerPrice` (check docs for supported param names)
	 * @param {object} [defaultValue] return default value if no result found
	 * @returns {object} returns feature value
	 */
	var methodName *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = methodName
	var paramName *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = paramName
	defaultValue := GetArg(optionalArgs, 2, nil)
	_ = defaultValue

	var market map[string]any = this.DerivedExchange.Market(symbol)
	return this.FeatureValueByType(market["type"], market["subType"], methodName, paramName, defaultValue)
}
func (this *BaseExchange) FeatureValueByType(marketType any, subType any, optionalArgs ...any) any {
	/**
	 * @method
	 * @name exchange#featureValueByType
	 * @description this method is a very deterministic to help users to know what feature is supported by the exchange
	 * @param {string} [marketType] supported only: "spot", "swap", "future"
	 * @param {string} [subType] supported only: "linear", "inverse"
	 * @param {string} [methodName] view currently supported methods: https://docs.ccxt.com/README?id=features
	 * @param {string} [paramName] unified param value (check docs for supported param names)
	 * @param {object} [defaultValue] return default value if no result found
	 * @returns {object} returns feature value
	 */
	// if exchange does not yet have features manually implemented
	methodName := GetArg(optionalArgs, 0, nil)
	_ = methodName
	paramName := GetArg(optionalArgs, 1, nil)
	_ = paramName
	defaultValue := GetArg(optionalArgs, 2, nil)
	_ = defaultValue
	if this.Features == nil {
		return defaultValue
	}
	if IsEqual(marketType, nil) {
		return defaultValue // marketType is required
	}
	// if marketType (e.g. 'option') does not exist in features
	if !(InOp(this.Features, marketType)) {
		return defaultValue // unsupported marketType, check "exchange.features" for details
	}
	var methodsContainer any = GetValue(this.Features, marketType)
	// if marketType dict undefined
	if IsEqual(methodsContainer, nil) {
		return defaultValue
	}
	if IsEqual(subType, nil) {
		if marketType != "spot" {
			return defaultValue // subType is required for non-spot markets
		}
	} else {
		if !(InOp(methodsContainer, subType)) {
			return defaultValue // unsupported subType, check "exchange.features" for details
		}
		methodsContainer = GetValue(methodsContainer, subType)
		// if subType dict undefined
		if IsEqual(methodsContainer, nil) {
			return defaultValue
		}
	}
	// if user wanted only marketType and didn't provide methodName, eg: featureIsSupported('spot')
	if methodName == nil {
		return func() any {
			if !IsEqual(defaultValue, nil) {
				return defaultValue
			}
			return methodsContainer
		}()
	}
	if !(InOp(methodsContainer, methodName)) {
		return defaultValue // unsupported method, check "exchange.features" for details');
	}
	var methodDict any = GetValue(methodsContainer, methodName)
	if methodDict == nil {
		return defaultValue
	}
	// if user wanted only method and didn't provide `paramName`, eg: featureIsSupported('swap', 'linear', 'createOrder')
	if paramName == nil {
		return func() any {
			if !IsEqual(defaultValue, nil) {
				return defaultValue
			}
			return methodDict
		}()
	}
	var splited []string = Split(paramName, ".") // can be only parent key (`stopLoss`) or with child (`stopLoss.triggerPrice`)
	var parentKey *string = SafeStringPtr(func() any {
		if 0 >= 0 && 0 < len(splited) {
			return splited[0]
		}
		return nil
	}())
	var subKey *string = this.SafeString(splited, 1)
	if !(InOp(methodDict, parentKey)) {
		return defaultValue // unsupported paramName, check "exchange.features" for details');
	}
	var dictionary map[string]any = SafeMapTyped(methodDict, parentKey)
	if dictionary == nil {
		// if the value is not dictionary but a scalar value (or undefined), return as is
		return GetValue(methodDict, parentKey)
	} else {
		// return as is, when calling without subKey eg: featureValueByType('spot', undefined, 'createOrder', 'stopLoss')
		if subKey == nil {
			return GetValue(methodDict, parentKey)
		}
		// throw an exception for unsupported subKey
		if !(InOp(GetValue(methodDict, parentKey), subKey)) {
			return defaultValue // unsupported subKey, check "exchange.features" for details
		}
		return GetValue(GetValue(methodDict, parentKey), subKey)
	}
}
func (this *BaseExchange) OrderbookChecksumMessage(symbol any) any {
	if IsEqual(symbol, nil) {
		panic(ArgumentsRequired(this.Id + " orderbookChecksumMessage() requires a symbol argument"))
	}
	return Add(symbol, " : orderbook data checksum validation failed. You can reconnect by calling watchOrderBook again or you can mute the error by setting exchange.options[\"watchOrderBook\"][\"checksum\"] = false")
}
