func (this *BaseExchange) fetchWebEndpointBody(ch chan AsyncResult[any], method any, endpointMethod any, returnAsJson any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	startRegex := GetArg(optionalArgs, 0, nil)
	_ = startRegex
	endRegex := GetArg(optionalArgs, 1, nil)
	_ = endRegex
	var options any = this.SafeValue(this.Options, method, map[string]any{})
	var muteOnFailure *bool = this.SafeBool(options, "webApiMuteFailure", true)

	{
		func(this *BaseExchange) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *BaseExchange) any {
						// catch block:
						if !(muteOnFailure != nil && *muteOnFailure) {
							panic(BadResponse(Add(Add(this.Id+" ", method), "() failed to fetch correct data from website. Probably webpage markup has been changed, breaking the page custom parser.")))
						}
						return nil
					}(this)
				}
			}()
			// try block:
			// if it was not explicitly disabled, then don't fetch
			if !(this.SafeBool(options, "webApiEnable", true) != nil && *this.SafeBool(options, "webApiEnable", true)) {

				return nil
			}
			var maxRetries int64 = *this.SafeInteger(options, "webApiRetries", 10)
			var response any = nil
			var shouldBreak bool = false
			for retry := 0; int64(retry) < maxRetries; retry++ {

				{
					func(this *BaseExchange) (ret_ any) {
						defer func() {
							if e := recover(); e != nil {
								if e == "break" {
									return
								}
								ret_ = func(this *BaseExchange) any {
									// catch block:
									if int64(retry+1) >= maxRetries {
										panic(e)
									}
									return nil
								}(this)
							}
						}()
						// try block:

						r := <-this.CallDynamically(endpointMethod, map[string]any{})
						if r.Err != nil {
							panic(r.Err)
						}
						response = r.Value
						shouldBreak = true
						panic("break")

					}(this)

				}
				if shouldBreak {
					break // this is needed because of GO
				}
			}
			var content any = response
			if IsEqual(content, nil) {
				panic(NullResponse(this.Id + " fetchWebEndpoint() returned empty content"))
			}
			if startRegex != nil {
				var splitted_by_start []string = Split(content, startRegex)
				content = func() any {
					if 1 >= 0 && 1 < len(splitted_by_start) {
						return splitted_by_start[1]
					}
					return nil
				}() // we need second part after start
			}
			if IsEqual(content, nil) {
				panic(NullResponse(this.Id + " fetchWebEndpoint() returned empty content"))
			}
			if endRegex != nil {
				var splitted_by_end []string = Split(content, endRegex)
				content = func() any {
					if 0 >= 0 && 0 < len(splitted_by_end) {
						return splitted_by_end[0]
					}
					return nil
				}() // we need first part after start
			}
			if (returnAsJson == true) && (IsString(content)) {
				var jsoned any = this.ParseJson(Trim(content)) // content should be trimmed before json parsing
				if jsoned != nil {

					ch <- AsyncResult[any]{Value: jsoned} // if parsing was not successfull, exception should be thrown
					chSent = true
					return nil
				} else {
					panic(BadResponse("could not parse the response into json"))
				}
			} else {

				ch <- AsyncResult[any]{Value: content}
				chSent = true
				return nil
			}

		}(this)
		if chSent {
			return nil
		}

	}

	return nil
}
