func (this *BaseExchange) SafeNetwork(network any) any {
	var withdrawEnabled *bool = this.SafeBool(network, "withdraw")
	var depositEnabled *bool = this.SafeBool(network, "deposit")
	var limits map[string]any = SafeMapTyped(network, "limits")
	var withdraw map[string]any = SafeMapTyped(limits, "withdraw")
	var deposit map[string]any = SafeMapTyped(limits, "deposit")
	var isEnabled *bool = withdrawEnabled
	if withdrawEnabled != nil && *withdrawEnabled == true {
		isEnabled = depositEnabled
	}
	return map[string]any{
		"info":      GetValue(network, "info"),
		"id":        this.SafeString(network, "id"),
		"name":      this.SafeString(network, "name"),
		"network":   this.SafeString(network, "network"),
		"active":    this.SafeBool(network, "active", isEnabled),
		"deposit":   depositEnabled,
		"withdraw":  withdrawEnabled,
		"fee":       this.SafeNumber(network, "fee"),
		"precision": this.SafeNumber(network, "precision"),
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": this.SafeNumber(withdraw, "min"),
				"max": this.SafeNumber(withdraw, "max"),
			},
			"deposit": map[string]any{
				"min": this.SafeNumber(deposit, "min"),
				"max": this.SafeNumber(deposit, "max"),
			},
		},
	}
}
func (this *BaseExchange) NetworkCodeToId(networkCode any, optionalArgs ...any) any {
	/**
	 * @ignore
	 * @method
	 * @name exchange#networkCodeToId
	 * @description tries to convert the provided networkCode (a unified network code or one of its aliases) to a network id. In order to achieve this, derived class needs to have 'options->networks' defined.
	 * @param {string} networkCode unified network code
	 * @param {string} currencyCode unified currency code, but this argument is not required by default, unless there is an exchange (like huobi) that needs an override of the method to be able to pass currencyCode argument additionally
	 * @returns {string|undefined} exchange-specific network id
	 */
	var currencyCode *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = currencyCode
	if IsEqual(networkCode, nil) {
		return nil
	}
	var unifiedCode *string = this.SafeString(this.NetworkAliases, networkCode, networkCode)
	var networkIdsByCodes map[string]any = SafeMapTyped(this.Options, "networks")
	var networkId *string = this.SafeString(networkIdsByCodes, unifiedCode)
	if networkId != nil {
		return networkId
	}
	// options.networks may still be keyed by an alias of the unified code
	var aliases any = this.NetworkAliases
	var aliasKeys []string = ObjectKeys(aliases)
	for i := 0; i < len(aliasKeys); i++ {
		var alias string = aliasKeys[i]
		if _, ok := networkIdsByCodes[alias]; (IsEqual(GetValue(aliases, alias), unifiedCode)) && ok {
			return networkIdsByCodes[alias]
		}
	}
	// fall back to scanning loaded currencies
	var currenciesToCheck any = []any{}
	if currencyCode == nil {
		var g04Keys []string = nil
		for k := range this.Currencies() {
			g04Keys = append(g04Keys, k)
		}
		currenciesToCheck = g04Keys
	} else {
		currenciesToCheck = []any{this.SafeDict(this.Currencies(), currencyCode)}
	}
	for i := 0; i < GetArrayLength(currenciesToCheck); i++ {
		var networks map[string]any = SafeMapTyped(GetValue(currenciesToCheck, i), "networks")
		if func() bool {
			if unifiedCode == nil {
				return false
			}
			_, ok := networks[*unifiedCode]
			return ok
		}() {
			return this.SafeString(func() any {
				if unifiedCode == nil {
					return nil
				}
				return networks[*unifiedCode]
			}(), "id")
		}
	}
	return networkCode
}
func (this *BaseExchange) NetworkIdToCode(optionalArgs ...any) *string {
	/**
	 * @ignore
	 * @method
	 * @name exchange#networkIdToCode
	 * @description tries to convert the provided exchange-specific networkId to an unified network Code. In order to achieve this, derived class needs to have "options['networksById']" defined.
	 * @param {string} networkId exchange specific network id/title, like: TRON, Trc-20, usdt-erc20, etc
	 * @param {string|undefined} currencyCode unified currency code, but this argument is not required by default, unless there is an exchange (like huobi) that needs an override of the method to be able to pass currencyCode argument additionally
	 * @returns {string|undefined} unified network code
	 */
	var networkId *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = networkId
	var currencyCode *string = GetArgStringPtr(optionalArgs, 1, nil)
	_ = currencyCode
	if networkId == nil {
		return SafeStringPtr(nil)
	}
	var networkCodesByIds map[string]any = SafeMapTyped(this.Options, "networksById")
	var mappedCode *string = this.SafeString(networkCodesByIds, networkId)
	var networkCode *string = func() *string {
		if mappedCode == nil {
			return networkId
		}
		return mappedCode
	}()
	return SafeStringPtr(this.SafeString(this.NetworkAliases, networkCode, networkCode))
}
func (this *BaseExchange) HandleNetworkCodeAndParams(params any) (*string, map[string]any) {
	var networkCodeInParams *string = this.SafeString2(params, "networkCode", "network")
	var paramsOmitted any = func() any {
		if networkCodeInParams != nil {
			return this.Omit(params, []any{"networkCode", "network"})
		}
		return params
	}()
	// if it was not defined by user, we should not set it from 'defaultNetworks', because handleNetworkCodeAndParams is for only request-side and thus we do not fill it with anything. We can only use 'defaultNetworks' after parsing response-side
	return networkCodeInParams, MapTyped(paramsOmitted)
}
func (this *BaseExchange) SelectNetworkKeyFromNetworks(currencyCode any, networkCode any, indexedNetworkEntries any, optionalArgs ...any) any {
	// this method is used against raw & unparse network entries, which are just indexed by network id
	var isIndexedByUnifiedNetworkCode bool = GetArgBool(optionalArgs, 0, false)
	_ = isIndexedByUnifiedNetworkCode
	var chosenNetworkId any = nil
	var availableNetworkIds []string = ObjectKeys(indexedNetworkEntries)
	var responseNetworksLength int = len(availableNetworkIds)
	if !IsEqual(networkCode, nil) {
		if responseNetworksLength == 0 {
			panic(NotSupported(Add(Add(Add(this.Id+" - ", networkCode), " network did not return any result for "), currencyCode)))
		} else {
			// if networkCode was provided by user, we should check it after response, as the referenced exchange doesn't support network-code during request
			var networkIdOrCode any = func() any {
				if isIndexedByUnifiedNetworkCode == true {
					return networkCode
				}
				return this.NetworkCodeToId(networkCode, currencyCode)
			}()
			if networkIdOrCode == nil {
				panic(NotSupported(Add(Add(Add(this.Id+" - ", networkCode), " network was not found for "), currencyCode)))
			}
			if InOp(indexedNetworkEntries, networkIdOrCode) {
				chosenNetworkId = networkIdOrCode
			} else {
				panic(NotSupported(Add(Add(Add(Add(Add(this.Id+" - ", networkIdOrCode), " network was not found for "), currencyCode), ", use one of "), strings.Join(availableNetworkIds, ", "))))
			}
		}
	} else {
		if responseNetworksLength == 0 {
			panic(NotSupported(Add(this.Id+" - no networks were returned for ", currencyCode)))
		} else {
			// if networkCode was not provided by user, then we try to use the default network (if it was defined in "defaultNetworks"), otherwise, we just return the first network entry
			var defaultNetworkCode *string = this.SafeString(this.SafeDict(this.Options, "defaultNetworks", map[string]any{}), currencyCode, this.SafeString(this.Options, "defaultNetwork"))
			var defaultNetworkId any = func() any {
				if isIndexedByUnifiedNetworkCode == true {
					return defaultNetworkCode
				}
				return this.NetworkCodeToId(defaultNetworkCode, currencyCode)
			}()
			if IsEqual(defaultNetworkId, nil) {
				panic(ExchangeError(this.Id + " selectNetworkKeyFromNetworks() missing defaultNetworkId"))
			}
			if InOp(indexedNetworkEntries, defaultNetworkId) {
				return defaultNetworkId
			}
			panic(NotSupported(this.Id + " - can not determine the default network, please pass param[\"network\"] one from : " + strings.Join(availableNetworkIds, ", ")))
		}
	}
	return chosenNetworkId
}
func (this *BaseExchange) ParseOrderBook(orderbook any, symbol any, optionalArgs ...any) map[string]any {
	var timestamp *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = timestamp
	var bidsKey string = GetArgString(optionalArgs, 1, "bids")
	_ = bidsKey
	var asksKey string = GetArgString(optionalArgs, 2, "asks")
	_ = asksKey
	priceKey := GetArg(optionalArgs, 3, 0)
	_ = priceKey
	amountKey := GetArg(optionalArgs, 4, 1)
	_ = amountKey
	countOrIdKey := GetArg(optionalArgs, 5, 2)
	_ = countOrIdKey

	var bids any = this.DerivedExchange.ParseOrderBookBidsAsks(this.SafeValue(orderbook, bidsKey, []any{}), priceKey, amountKey, countOrIdKey)
	PanicOnError(bids)

	var asks any = this.DerivedExchange.ParseOrderBookBidsAsks(this.SafeValue(orderbook, asksKey, []any{}), priceKey, amountKey, countOrIdKey)
	PanicOnError(asks)
	return map[string]any{
		"symbol":    symbol,
		"bids":      this.SortBy(bids, 0, true),
		"asks":      this.SortBy(asks, 0),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"nonce":     nil,
	}
}
