func (this *BaseExchange) CleanUnsubscription(client *Client, subHash any, unsubHash any, optionalArgs ...any) {
	var subHashIsPrefix bool = GetArgBool(optionalArgs, 0, false)
	_ = subHashIsPrefix
	if (!IsEqual(unsubHash, nil)) && (client.SubscriptionHas(unsubHash)) {
		client.SubscriptionDel(unsubHash)
	}
	if !IsEqual(subHash, nil) {
		if !(subHashIsPrefix == true) {
			if client.SubscriptionHas(subHash) {
				client.SubscriptionDel(subHash)
			}
			if InOp(client.Futures, subHash) {
				error := UnsubscribeError(Add(this.Id+" ", subHash))
				client.Reject(error, subHash)
			}
		} else {
			var clientSubscriptions []string = client.SubscriptionKeys()
			for i := 0; i < len(clientSubscriptions); i++ {
				var sub string = clientSubscriptions[i]
				if StartsWith(sub, subHash) {
					client.SubscriptionDel(sub)
				}
			}
			var clientFutures []string = ObjectKeys(client.Futures)
			for i := 0; i < len(clientFutures); i++ {
				var future string = clientFutures[i]
				if StartsWith(future, subHash) {
					error := UnsubscribeError(this.Id + " " + future)
					client.Reject(error, future)
				}
			}
		}
	}
	client.Resolve(true, unsubHash)
}
func (this *BaseExchange) CleanCache(subscription any) {
	var topic *string = this.SafeString(subscription, "topic")
	var symbols []any = SafeListTyped(subscription, "symbols")
	var symbolsLength int = len(symbols)
	if topic != nil && *topic == "ohlcv" {
		var symbolsAndTimeframes []any = SafeListTyped(subscription, "symbolsAndTimeframes")
		for i := 0; i < len(symbolsAndTimeframes); i++ {
			var symbolAndTimeFrame any = symbolsAndTimeframes[i]
			var symbol *string = this.SafeString(symbolAndTimeFrame, 0)
			var timeframe *string = this.SafeString(symbolAndTimeFrame, 1)
			if symbol == nil {
				panic(ArgumentsRequired(this.Id + " cleanCache() requires a symbol argument"))
			}
			if timeframe == nil {
				panic(ArgumentsRequired(this.Id + " cleanCache() requires a timeframe argument"))
			}
			if _, ok := this.Ohlcvs[*symbol]; ok {
				if InOp(this.Ohlcvs[*symbol], timeframe) {
					delete(this.Ohlcvs[*symbol], *timeframe)
				}
			}
		}
	} else if symbolsLength > 0 {
		for i := 0; i < len(symbols); i++ {
			var symbol *string = this.SafeString(symbols, i, "")
			if topic != nil && *topic == "trades" {
				if _, ok := this.Trades[*symbol]; ok {
					delete(this.Trades, *symbol)
				}
			} else if topic != nil && *topic == "orderbook" {
				if this.Orderbooks.Has(symbol) {
					delete(this.Orderbooks, *symbol)
				}
			} else if topic != nil && *topic == "ticker" {
				if this.Tickers.Has(symbol) {
					this.Tickers.Delete(*symbol)
				}
			} else if topic != nil && *topic == "bidsasks" {
				if this.Bidsasks.Has(symbol) {
					this.Bidsasks.Delete(*symbol)
				}
			}
		}
	} else {
		if topic != nil && *topic == "myTrades" {
			this.MyTrades = nil
		} else if topic != nil && *topic == "orders" {
			this.Orders = nil
		} else if (topic != nil && *topic == "positions") && (!IsEqual(this.Positions, nil)) {
			this.Positions = nil
			var clients []any = ObjectValues(this.WsClientsSnapshot())
			for i := 0; i < len(clients); i++ {
				var client any = DerefScalar(clients[i])
				var futures any = (client.(Client)).Futures
				if InOp(futures, "fetchPositionsSnapshot") {
					Remove(futures, "fetchPositionsSnapshot")
				}
			}
		} else if ((topic != nil && *topic == "ticker") || (topic != nil && *topic == "markPrice")) && (this.Tickers != nil) {
			var tickerSymbols []string = this.Tickers.Keys()
			for i := 0; i < len(tickerSymbols); i++ {
				var tickerSymbol string = tickerSymbols[i]
				if this.Tickers.Has(tickerSymbol) {
					this.Tickers.Delete(tickerSymbol)
				}
			}
		} else if (topic != nil && *topic == "bidsasks") && (this.Bidsasks != nil) {
			var bidsaskSymbols []string = this.Bidsasks.Keys()
			for i := 0; i < len(bidsaskSymbols); i++ {
				var bidsaskSymbol string = bidsaskSymbols[i]
				if this.Bidsasks.Has(bidsaskSymbol) {
					this.Bidsasks.Delete(bidsaskSymbol)
				}
			}
		}
	}
}
func (this *BaseExchange) TimeframeFromMilliseconds(ms any) any {
	var msInt int64 = this.ParseToInt(ms)
	if msInt <= 0 {
		return ""
	}
	var second int = 1000
	var minute int64 = 60 * int64(second)
	var hour int64 = 60 * minute
	var day int64 = 24 * hour
	var week int64 = 7 * day
	if (msInt % week) == 0 {
		return strconv.FormatInt(this.ParseToInt(float64(msInt)/float64(week)), 10) + "w"
	}
	if (msInt % day) == 0 {
		return strconv.FormatInt(this.ParseToInt(float64(msInt)/float64(day)), 10) + "d"
	}
	if (msInt % hour) == 0 {
		return strconv.FormatInt(this.ParseToInt(float64(msInt)/float64(hour)), 10) + "h"
	}
	if (msInt % minute) == 0 {
		return strconv.FormatInt(this.ParseToInt(float64(msInt)/float64(minute)), 10) + "m"
	}
	if msInt%1000 == 0 {
		return strconv.FormatInt(this.ParseToInt(float64(msInt)/1000), 10) + "s"
	}
	return ""
}
